mapper.select:
           select  a.bookset_id booksetId,a.bookset_name booksetName from BOK_BOOKSET a where 1=1

           		and a.bookSet_Type=#{bookSetType}  


        		AND (
			   bookset_id like concat_ws('','%',#{search,jdbcType=VARCHAR},'%')
			   or
			   bookset_name like concat_ws('','%',#{search,jdbcType=VARCHAR},'%')
			   )


	        	AND  vb.BOOKSET_ID in

	         		#{item}




	            and a.ACCT_SUBJECT_TYPE != #{acctSubjectTypeNo}

SELECT vb.bookset_id as booksetId, DATE_FORMAT(vb.bookset_date,'%Y-%m-%d') as booksetDate, bb.BOOKSET_NAME as booksetName, DATE_FORMAT(bb.START_DATE,'%Y-%m-%d') as startDate, DATE_FORMAT(bb.END_DATE,'%Y-%m-%d') as endDate FROM BOK_BOOKSET_DATE vb LEFT JOIN BOK_BOOKSET bb ON bb.BOOKSET_ID = vb.BOOKSET_ID WHERE bb.BOOKSET_TYPE = #{booksetType}
AND vb.BOOKSET_ID in
#{item}

     	select
	     	tc.happenDate,
		    tc.booksetDate,
		    tc.bookDate,
		    tc.booksetId,
		    tc.bokDetailId,
		    tc.invAim
	    from (
	    	SELECT 
				TL.HAPPEN_DATE as happenDate,--发生日期
				TL.BOOKSET_DATE as booksetDate,--账套日期
				TL.BOOK_DATE as bookDate,--入账日期
				TL.BOOKSET_ID as booksetId, --账套代码
				TL.BUSI_ID as bokDetailId,--业务明细代码
				case when(JY.INV_AIM IS NOT NULL AND JY.C_INV_AIM IN('FVTPL','FVOCI'))
				then JY.C_INV_AIM
				ELSE TL.INV_AIM
				END AS invAim
			FROM (
				select
					temp.HAPPEN_DATE,
					temp.BOOKSET_DATE,
					temp.BOOK_DATE,
					temp.BOOKSET_ID,
					temp.BUSI_ID,
					temp.INV_AIM,
					temp.FINPROD_TYPE
				from (
		select
		bp.*,
		rn
		from (
		/* 子查询必加上rn字段 */
		SELECT result.* FROM (
		SELECT tmp.*,
		@rownum := @rownum + 1 row, /* 虚拟列行标 */
		IF(
		(
		@BOOKSET_ID = tmp.BOOKSET_ID and
		@BOK_DETAIL_ID = tmp.BOK_DETAIL_ID and
		@HAPPEN_DATE  = tmp.HAPPEN_DATE
		),
		@rank := @rank + 1,
		@rank := 1
		) AS rn, /* 分组虚拟列行标 */
		/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
		@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
		, @BOK_DETAIL_ID := tmp.BOK_DETAIL_ID /* 分组条件2 */
		, @HAPPEN_DATE := tmp.HAPPEN_DATE /* 分组条件3 */
		FROM (
		/* 数据源 */
		SELECT bc.*
		FROM BOK_STAT_DET_POSIITON bc
		ORDER BY CAST(bc.BOOK_SUMMARY_ORDER as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
		) tmp,
		/* 定义临时变量池 */
		(SELECT @rownum := 0,
		@BOOKSET_ID := null,
		@BOK_DETAIL_ID = null,
		@HAPPEN_DATE = null,
		@rank := 0) a
		) result
		) bp
		where bp.FINPROD_TYPE='F01' --债券
		and bp.INV_AIM !='AC'
		and bp.BOOK_DATE <=STR_TO_DATE(#{NOW(),jdbcType=VARCHAR},'%Y-%m-%d')
		and bp.HAPPEN_DATE <=STR_TO_DATE(#{NOW(),jdbcType=VARCHAR},'%Y-%m-%d')
		and bp.POS_AMT!=0

			and bp.BOOKSET_ID  in

				#{item}


		) temp
				where temp.riw=1
			)TL LEFT JOIN (
				SELECT
					td.FINPROD_ID,
					td.FINPROD_TYPE,
					td.INV_AIM,
					tb.INV_AIM as C_INV_AIM,
					ba.BOOKSET_ID
				FROM TRD_FIN_PRODUCT_BARTER tb
				inner join TRD_PRODUCT_DEAL td on tb.TRADE_ID=td.TRADE_ID
				and tb.FINPROD_ID=td.FINPROD_ID
				and tb.FINPROD_TYPE=td.FINPROD_TYPE
				inner join BOK_DEAL_ACCOUNTING ba on tb.TRADE_ID=ba.BUSI_NO
				--入账信息�?.业务�?=交易�?
				where tb.FINPROD_TYPE='F01' --债券
				and td.TRADE_DATE=STR_TO_DATE(#{NOW(),jdbcType=VARCHAR},'%Y-%m-%d')  --平台日期�?
			) JY ON TL.BOOKSET_ID=JY.BOOKSET_ID
			AND TL.BUSI_ID=JY.FINPROD_ID
			AND TL.FINPROD_TYPE=JY.FINPROD_TYPE
			AND TL.INV_AIM=JY.INV_AIM
		) tc group by tc.happenDate,tc.booksetDate,tc.bookDate,tc.booksetId,tc.bokDetailId,tc.invAim

